use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl ReplState { fn new () -> Self { Self { system : Output2MacroSystem :: import_from_output2 () . unwrap_or_else (| _ | { Output2MacroSystem { macros : HashMap :: new () , interpreter : LispInterpreter :: new () , } }) , variables : HashMap :: new () , history : Vec :: new () , } } fn load_from_file () -> Result < Self > { Self :: load_from_file_path (STATE_FILE) } fn load_from_file_path (path : & str) -> Result < Self > { if Path :: new (path) . exists () { let rdf_content = fs :: read_to_string (path) ? ; let blob = RdfUrlBlob :: from_url_blob (& rdf_content) ? ; let mut state = Self :: new () ; for line in blob . rdf_content . lines () { if line . starts_with ("# var:") { if let Some ((key , value)) = line [6 ..] . split_once ("=") { state . variables . insert (key . trim () . to_string () , value . trim () . to_string ()) ; } } } println ! ("📂 Loaded state from {}" , path) ; Ok (state) } else { println ! ("🆕 Starting fresh REPL session") ; Ok (Self :: new ()) } } fn load_from_url (url : & str) -> Result < Self > { println ! ("🌐 Loading state from URL: {}" , url) ; let raw_url = if url . contains ("github.com") && url . contains ("/blob/") { url . replace ("github.com" , "raw.githubusercontent.com") . replace ("/blob/" , "/") } else { url . to_string () } ; let content = std :: process :: Command :: new ("curl") . arg ("-s") . arg (& raw_url) . output () ? ; if ! content . status . success () { return Err (anyhow :: anyhow ! ("Failed to fetch URL: {}" , raw_url)) ; } let code_content = String :: from_utf8 (content . stdout) ? ; let mut state = Self :: new () ; let filename = url . split ('/') . last () . unwrap_or ("unknown") ; let macro_name = filename . trim_end_matches (".rs") . replace ("_decls_" , "_") ; let decl = MacroDeclaration { name : macro_name . clone () , source_path : url . to_string () , declaration_type : "declaration" . to_string () , content : code_content , wrapper : None , } ; state . system . macros . insert (macro_name . clone () , decl) ; println ! ("✅ Loaded declaration as macro: {}" , macro_name) ; Ok (state) } fn save_to_file (& self) -> Result < () > { let blob = RdfUrlBlob :: from_system_state (& self . system) ? ; let mut enhanced_rdf = String :: new () ; enhanced_rdf . push_str ("# REPL State Variables\n") ; for (key , value) in & self . variables { enhanced_rdf . push_str (& format ! ("# var:{}={}\n" , key , value)) ; } enhanced_rdf . push_str ("\n") ; enhanced_rdf . push_str (& blob . rdf_content) ; fs :: write (STATE_FILE , blob . url_blob) ? ; println ! ("💾 State saved to {}" , STATE_FILE) ; Ok (()) } }